#!/usr/bin/env python3
"""Blind re-derivation for TASK-20260927-7d51ae (NJ6). Independent implementation.

Reads only the two amendment files (for hash and span checks). All recipes are
implemented from their text. No integer is transcribed from any source.
"""
import hashlib, json, math, subprocess, sys, time, ast
from math import isqrt, gcd
from decimal import Decimal, getcontext
import mpmath
import sympy
import yaml

WT = "/Volumes/SSD990/crypto-autoresearcher/.worktrees/ecdlp-9225d2-revise-20260927/"
TYPED = WT + "experiments/EXP-AUXIN-7e2e3d/amendments/AMD-20260926-typed.yaml"
NARROW = WT + "experiments/EXP-AUXIN-7e2e3d/amendments/AMD-20260927-narrow.yaml"
OUT = {}

def sha(path):
    return hashlib.sha256(open(path, "rb").read()).hexdigest()

# ---------------------------------------------------------------- Q0 hash + spans
typed_sha = sha(TYPED)
narrow = yaml.safe_load(open(NARROW))["amendment"]
typed = yaml.safe_load(open(TYPED))["amendment"]
OUT["hash_check"] = {
    "typed_sha256_computed": typed_sha,
    "typed_sha256_stated": narrow["incorporates"]["sha256"],
    "match": typed_sha == narrow["incorporates"]["sha256"],
    "narrow_sha256_computed": sha(NARROW),
}

def by_id(lst, key, val):
    for x in lst:
        if isinstance(x, dict) and x.get(key) == val:
            return x
    raise KeyError(val)

def resolve(field):
    f = field
    if f.startswith("change.D1_pins.rows[BN254-r]."):
        return by_id(typed["change"]["D1_pins"]["rows"], "id", "BN254-r")[f.split(".")[-1]]
    if f.startswith("success_criterion.outcomes["):
        oid = f.split("[")[1].split("]")[0]
        return by_id(typed["success_criterion"]["outcomes"], "id", oid)["condition"]
    node = typed
    for part in f.split("."):
        node = node[part]
    return node

span_results = []
for sr in narrow["span_rules"]:
    val = resolve(sr["field"])
    fr, th = sr["from"], sr["through"]
    n_from = val.count(fr)
    i = val.find(fr)
    j = val.find(th, i)
    span = val[i:j + len(th)] if (i >= 0 and j >= 0) else None
    h = hashlib.sha256(span.encode()).hexdigest() if span is not None else None
    combined = (val[:i] + sr["replacement"] + val[j + len(th):]) if span is not None else None
    span_results.append({
        "id": sr["id"], "field": sr["field"], "from_occurrences": n_from,
        "span_found": span is not None, "span_sha256": h,
        "stated_sha256": sr["replaced_span_sha256"],
        "match": h == sr["replaced_span_sha256"],
        "combined_text": combined if sr["id"] in ("FP-DEF", "BINS-EXACT", "CTRL-FIELD") else None,
    })
OUT["span_checks"] = span_results

# ---------------------------------------------------------------- primality screen
SMALL = list(sympy.primerange(2, 20000))

def jacobi(a, n):
    a %= n
    res = 1
    while a:
        while a % 2 == 0:
            a //= 2
            if n % 8 in (3, 5):
                res = -res
        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
            res = -res
        a %= n
    return res if n == 1 else 0

def strong_prp2(n):
    d, s = n - 1, 0
    while d % 2 == 0:
        d //= 2; s += 1
    x = pow(2, d, n)
    if x in (1, n - 1):
        return True
    for _ in range(s - 1):
        x = x * x % n
        if x == n - 1:
            return True
    return False

def strong_lucas(n):
    r = isqrt(n)
    if r * r == n:
        return False
    D = 5
    while True:
        j = jacobi(D, n)
        if j == -1:
            break
        if j == 0 and abs(D) < n:
            return False
        D = -D - 2 if D > 0 else -D + 2
    P, Q = 1, (1 - D) // 4
    d, s = n + 1, 0
    while d % 2 == 0:
        d //= 2; s += 1
    inv2 = (n + 1) // 2
    U, V, Qk = 0, 2, 1
    for bit in bin(d)[2:]:
        U = U * V % n
        V = (V * V - 2 * Qk) % n
        Qk = Qk * Qk % n
        if bit == "1":
            U, V = (P * U + V) * inv2 % n, (D * U + P * V) * inv2 % n
            Qk = Qk * Q % n
    if U == 0 or V == 0:
        return True
    for _ in range(s - 1):
        V = (V * V - 2 * Qk) % n
        Qk = Qk * Qk % n
        if V == 0:
            return True
    return False

def bpsw(n):
    if n < 2:
        return False
    for p in SMALL[:200]:
        if n == p:
            return True
        if n % p == 0:
            return False
    return strong_prp2(n) and strong_lucas(n)

def nextprime_ge(x):
    n = x
    while not bpsw(n):
        n += 1
    return n

def icbrt(n):
    if n < 8:
        return 1 if n >= 1 else 0
    x = 1 << ((n.bit_length() + 2) // 3 + 1)  # strict overestimate; Newton decreases monotonically to floor
    while True:
        y = (2 * x + n // (x * x)) // 3
        if y >= x:
            break
        x = y
    while x * x * x > n:
        x -= 1
    while (x + 1) ** 3 <= n:
        x += 1
    return x

def ceildiv(a, b):
    return -(-a // b)

# sieve search over n = start, start+1, ... ; forms (a, b, excluded_primes): a*n + b
def sieve_search(start, forms, accept, block=1 << 16, limit=1 << 48):
    primes = SMALL[1:]  # odd primes; parity handled by forms themselves
    base = start
    while base < start + limit:
        alive = bytearray([1]) * block
        for p in [2] + primes:
            for (a, b, excl) in forms:
                if p in excl:
                    continue
                a_p = a % p
                if a_p == 0:
                    if b % p == 0:
                        alive = bytearray(block)
                    continue
                # a*n + b == 0 mod p  <=>  n == -b * a^-1 mod p
                n0 = (-b * pow(a_p, -1, p)) % p
                off = (n0 - base) % p
                alive[off::p] = bytearray(len(range(off, block, p)))
        for i in range(block):
            if alive[i]:
                n = base + i
                if accept(n):
                    return n
        base += block
    return None

def construct():
    R = {}
    B = 256; M0 = 3 * 2 ** (B - 2)
    BL = 521; ML = 3 * 2 ** (BL - 2)
    R["constants"] = {"B": B, "M0": M0, "B_L": BL, "M_L": ML}

    # C-PLANT-M
    S = isqrt(M0); s0 = isqrt(S)
    d1 = nextprime_ge(s0); d2 = nextprime_ge(d1 + 1)
    D = d1 * d2; u0 = ceildiv(M0, 2 * D)
    def accM(u):
        if u in (d1, d2):
            return False
        if not bpsw(u):
            return False
        r = 2 * D * u + 1
        if not bpsw(r):
            return False
        if (r + 1) % 12:
            return False
        return bpsw((r + 1) // 12)
    t = time.time()
    u = sieve_search(u0, [(1, 0, ()), (2 * D, 1, ()), (D, 1, (2, 3))], accM)
    r = 2 * D * u + 1; v = (r + 1) // 12
    R["C-PLANT-M"] = dict(S=S, isqrt_S=s0, d1=d1, d2=d2, D=D, u0=u0, u=u, r=r, v=v,
        candidates={"d1": d1 - s0 + 1, "d2": d2 - d1, "u": u - u0 + 1},
        windows={"d1": s0 <= d1 < s0 + 2 ** 24, "d2": d1 < d2 < d1 + 2 ** 24,
                 "u": u0 <= u < u0 + 2 ** 48, "r_bits_is_B": r.bit_length() == B},
        seconds=round(time.time() - t, 2))

    # C-PLANT-P
    assert M0 % 4 == 0
    d0 = icbrt(M0 // 4); d = nextprime_ge(d0); w0 = ceildiv(M0, 12 * d)
    def accP(w):
        if w == d or not bpsw(w):
            return False
        r_ = 12 * d * w - 1
        return bpsw(r_) and bpsw((r_ - 1) // 2)
    t = time.time()
    w = sieve_search(w0, [(1, 0, ()), (12 * d, -1, ()), (6 * d, -1, ())], accP)
    rP = 12 * d * w - 1; qP = (rP - 1) // 2
    R["C-PLANT-P"] = dict(d0=d0, d=d, w0=w0, w=w, r=rP, q=qP,
        candidates={"d": d - d0 + 1, "w": w - w0 + 1},
        windows={"d": d0 <= d < d0 + 2 ** 24, "w": w0 <= w < w0 + 2 ** 48,
                 "r_bits_is_B": rP.bit_length() == B,
                 "declared_size": (d.bit_length() in (d0.bit_length(), d0.bit_length() + 1)) and d >= d0},
        seconds=round(time.time() - t, 2))

    # C-INERT
    w0 = 2 ** (B - 4); assert 12 * w0 == M0
    def accI(w):
        return bpsw(w) and bpsw(12 * w - 1) and bpsw(6 * w - 1)
    t = time.time()
    wI = sieve_search(w0, [(1, 0, ()), (12, -1, ()), (6, -1, ())], accI)
    R["C-INERT"] = dict(w0=w0, w=wI, r=12 * wI - 1, q=6 * wI - 1,
        candidates={"w": wI - w0 + 1},
        windows={"w": w0 <= wI < w0 + 2 ** 48, "r_bits_is_B": (12 * wI - 1).bit_length() == B},
        seconds=round(time.time() - t, 2))

    # C-PLANT-PL
    assert ML % 4 == 0
    xL = icbrt(ML // 4)
    f1 = nextprime_ge(2 ** 43); f2 = nextprime_ge(f1 + 1); f3 = nextprime_ge(f2 + 1)
    G = f1 * f2 * f3; y = ceildiv(xL, G); f4 = nextprime_ge(y); DL = G * f4
    w0 = ceildiv(ML, 12 * DL)
    def accL(w):
        if not bpsw(w):
            return False
        r_ = 12 * DL * w - 1
        return bpsw(r_) and bpsw((r_ - 1) // 2)
    t = time.time()
    wL = sieve_search(w0, [(1, 0, ()), (12 * DL, -1, ()), (6 * DL, -1, ())], accL)
    rL = 12 * DL * wL - 1
    R["C-PLANT-PL"] = dict(x_L=xL, f1=f1, f2=f2, f3=f3, G=G, y=y, f4=f4, D_L=DL, w0=w0, w=wL,
        r=rL, q=(rL - 1) // 2,
        candidates={"f1": f1 - 2 ** 43 + 1, "f2": f2 - f1, "f3": f3 - f2, "f4": f4 - y + 1, "w": wL - w0 + 1},
        windows={"f1": 2 ** 43 <= f1 < 2 ** 43 + 2 ** 24, "f2": f1 < f2 < f1 + 2 ** 24,
                 "f3": f2 < f3 < f2 + 2 ** 24, "f4": (y <= f4 < y + 2 ** 24) and f4 > f3,
                 "w": w0 <= wL < w0 + 2 ** 48, "r_bits_is_B_L": rL.bit_length() == BL,
                 "D_L_in_[x_L,x_L(1+2^-19))": xL <= DL < xL + (xL >> 19)},
        seconds=round(time.time() - t, 2))

    # C-FIELD
    R["C-FIELD"] = {"CF-1": 2 ** 255 - 19, "CF-2": 2 ** 256 - 2 ** 224 + 2 ** 192 + 2 ** 96 - 1}
    return R

# ---------------------------------------------------------------- certificates
def factor_small(n):
    return {int(k): int(v) for k, v in sympy.factorint(n).items()}

def pratt(p, depth=0):
    """Pratt certificate (recursive) for p < 2^64 or ECPP terminal primes."""
    if p == 2:
        return {"p": 2, "kind": "pratt_leaf"}
    fac = factor_small(p - 1)
    a = 2
    while True:
        if pow(a, p - 1, p) == 1 and all(pow(a, (p - 1) // f, p) != 1 for f in fac):
            break
        a += 1
    return {"p": p, "kind": "pratt", "a": a, "factors": {str(f): e for f, e in fac.items()},
            "sub": [pratt(f, depth + 1) for f in fac if f != 2] }

def verify_pratt(c):
    p = c["p"]
    if c["kind"] == "pratt_leaf":
        return p == 2
    fac = {int(k): v for k, v in c["factors"].items()}
    prod = 1
    for f, e in fac.items():
        prod *= f ** e
    if prod != p - 1:
        return False
    a = c["a"]
    if pow(a, p - 1, p) != 1:
        return False
    if any(pow(a, (p - 1) // f, p) == 1 for f in fac):
        return False
    subs = {s["p"]: s for s in c["sub"]}
    for f in fac:
        if f == 2:
            continue
        if f not in subs or not verify_pratt(subs[f]):
            return False
    return True

def gp_primecert(n):
    out = subprocess.run(["gp", "-q", "-f", "--default", "parisizemax=2000000000"],
                         input=f"print(primecert({n}))\n", capture_output=True, text=True, timeout=3600)
    return ast.literal_eval(out.stdout.strip())

def ec_add(P, Q, a4, N):
    if P is None: return Q
    if Q is None: return P
    x1, y1 = P; x2, y2 = Q
    if x1 == x2:
        if (y1 + y2) % N == 0:
            return None
        num, den = (3 * x1 * x1 + a4) % N, (2 * y1) % N
    else:
        num, den = (y2 - y1) % N, (x2 - x1) % N
    if gcd(den, N) != 1:
        raise ValueError("non-invertible denominator")
    lam = num * pow(den, -1, N) % N
    x3 = (lam * lam - x1 - x2) % N
    return (x3, (lam * (x1 - x3) - y1) % N)

def ec_mul(k, P, a4, N):
    R = None
    for bit in bin(k)[2:]:
        R = ec_add(R, R, a4, N)
        if bit == "1":
            R = ec_add(R, P, a4, N)
    return R

def verify_ecpp(cert, N0):
    """Independent check of a PARI primecert chain per the typed text's criterion list."""
    Nexp = N0
    for step in cert:
        N, t, s, a4, P = step
        x, y = P
        if N != Nexp or gcd(N, 6) != 1:
            return False, "N/gcd"
        m = N + 1 - t
        if m % s:
            return False, "s|m"
        q = m // s
        b = (y * y - x ** 3 - a4 * x) % N
        if gcd(4 * a4 ** 3 + 27 * b * b, N) != 1:
            return False, "disc"
        try:
            sP = ec_mul(s, (x % N, y % N), a4 % N, N)
            if sP is None:
                return False, "[s]P infinity"
            mP = ec_mul(q, sP, a4 % N, N)
        except ValueError:
            return False, "denominator"
        if mP is not None:
            return False, "[m]P != O"
        # least c with c^4 >= N
        lo, hi = 0, 1 << (N.bit_length() // 4 + 2)
        while lo < hi:
            mid = (lo + hi) // 2
            if mid ** 4 >= N: hi = mid
            else: lo = mid + 1
        c = lo
        if not q > (c + 1) ** 2:
            return False, "q bound"
        Nexp = q
    term = pratt(Nexp)
    return verify_pratt(term), {"terminal_q": Nexp, "terminal_pratt_ok": verify_pratt(term)}

def certify(n):
    if n < 2 ** 64:
        c = pratt(n)
        return {"kind": "pratt", "verified": verify_pratt(c), "cert": c}
    cert = gp_primecert(n)
    ok, info = verify_ecpp(cert, n)
    return {"kind": "ecpp(PARI primecert)+pratt terminal", "steps": len(cert), "verified": bool(ok),
            "detail": info if isinstance(info, dict) else info,
            "cert_sha256": hashlib.sha256(json.dumps(cert).encode()).hexdigest()}

# ---------------------------------------------------------------- evaluation
mpmath.mp.dps = 200
getcontext().prec = 200

def divisors_from(fac):
    ds = [1]
    for p, e in fac.items():
        ds = [d * p ** k for d in ds for k in range(e + 1)]
    return sorted(set(ds))

class PathA:
    @staticmethod
    def log2(x): return mpmath.log(mpmath.mpf(x), 2)
    @staticmethod
    def sqrt(x): return mpmath.sqrt(x)
    @staticmethod
    def num(x): return mpmath.mpf(x)

LN2 = Decimal(2).ln()
class PathB:
    @staticmethod
    def log2(x): return Decimal(x).ln() / LN2
    @staticmethod
    def sqrt(x): return Decimal(x).sqrt()
    @staticmethod
    def num(x): return Decimal(x)

def T(P, branch, r, d):
    m = r - 1 if branch == "minus" else r + 1
    if branch == "minus":
        return P.sqrt(P.num(m) / P.num(d)) + P.sqrt(P.num(d))
    return P.sqrt(P.num(m) / P.num(d)) + P.num(d)

def e_of(P, branch, r, d):
    return P.log2(T(P, branch, r, d)) / P.log2(r)

def floor_F(P, branch, r):
    if branch == "minus":
        return (1 + P.log2(r - 1) / 4) / P.log2(r)
    return (P.log2(3) - P.num(2) / 3 + P.log2(r + 1) / 3) / P.log2(r)

def ceil_C(P, branch, r):
    m = r - 1 if branch == "minus" else r + 1
    return P.log2(P.sqrt(P.num(m)) + 1) / P.log2(r)

TAU_A = mpmath.mpf(10) ** -45
TAU_B = Decimal(10) ** -45

def bin_exact(P, s):
    tau = TAU_A if P is PathA else TAU_B
    q1, q3 = P.num(1) / 4, P.num(3) / 4
    flag = abs(s - q1) <= tau or abs(s - q3) <= tau
    if flag:
        b = "INTERMEDIATE" if abs(s - q3) <= tau else "NEAR_CEILING"
    elif s >= q3 + tau:
        b = "NEAR_FLOOR"
    elif s <= q1 - tau:
        b = "NEAR_CEILING"
    else:
        b = "INTERMEDIATE"
    return b, flag

def evaluate(P, branch, r, cand, status):
    vals = [(e_of(P, branch, r, d), d) for d in cand]
    estar = min(v for v, _ in vals)
    tied = sorted(d for v, d in vals if v - estar <= P.num(10) ** -100 * estar)
    dmin = tied[0]
    F, C = floor_F(P, branch, r), ceil_C(P, branch, r)
    e = e_of(P, branch, r, dmin)
    s = (C - e) / (C - F)
    b, flag = bin_exact(P, s)
    tau = TAU_A if P is PathA else TAU_B
    if status == "EXACT":
        bn, bal = b, b
    else:
        if (not flag) and s >= P.num(3) / 4 + tau:
            bn, bal = "NEAR_FLOOR", "NEAR_FLOOR"
        else:
            bn, bal = "UNDETERMINED", b
    floor_ok = e >= F - tau and all((T(P, branch, r, d) >= P.num(d)) for d in cand) if branch == "plus" else e >= F - tau
    return dict(status=status, minimiser=dmin, tied=tied, e=e, F=F, C=C, depth=s, bin=bn,
                bin_at_least=bal, boundary_flag=flag, e_minus_F=e - F,
                log2_T_witness=P.log2(T(P, branch, r, dmin)), log2_T_floor=F * P.log2(r),
                floor_invariant_ok=bool(floor_ok))

def witness_set(Ffac, parts):
    ds = divisors_from(Ffac)
    W = set()
    for mask in range(1 << len(parts)):
        prod = 1
        for i, p in enumerate(parts):
            if mask >> i & 1:
                prod *= p
        for e in ds:
            W.add(e * prod)
    return sorted(W)

def fmt(x, digits=60):
    if isinstance(x, (mpmath.mpf,)):
        return mpmath.nstr(x, digits)
    if isinstance(x, Decimal):
        return format(x, f".{digits}g")
    return x

def both(branch, r, cand, status):
    a = evaluate(PathA, branch, r, cand, status)
    b = evaluate(PathB, branch, r, cand, status)
    agree = {k: (abs(Decimal(mpmath.nstr(a[k], 120)) - b[k]) <= Decimal(10) ** -50)
             for k in ("e", "F", "C", "depth", "log2_T_witness", "log2_T_floor")}
    cat = {k: a[k] == b[k] for k in ("status", "minimiser", "bin", "bin_at_least", "boundary_flag")}
    res = {k: (fmt(v) if isinstance(v, (mpmath.mpf,)) else v) for k, v in a.items()}
    res["path_agreement_numeric_1e-50"] = agree
    res["path_agreement_categorical"] = cat
    res["log2_T_witness_4dp"] = mpmath.nstr(a["log2_T_witness"], 10)
    res["log2_T_floor_4dp"] = mpmath.nstr(a["log2_T_floor"], 10)
    res["e_minus_F_margin_to_1e-6"] = mpmath.nstr(mpmath.mpf(10) ** -6 - a["e_minus_F"], 20)
    return res

def main():
    t0 = time.time()
    R = construct()
    OUT["constructions"] = {k: ({kk: (str(vv) if isinstance(vv, int) and not isinstance(vv, bool) else vv)
                                 for kk, vv in v.items()} if isinstance(v, dict) else v) for k, v in R.items()}
    # bit lengths
    bits = {}
    for c, v in R.items():
        if c == "constants":
            continue
        bits[c] = {k: vv.bit_length() for k, vv in v.items() if isinstance(vv, int) and not isinstance(vv, bool)}
    OUT["bit_lengths"] = bits

    M, Pp, I, L, CF = R["C-PLANT-M"], R["C-PLANT-P"], R["C-INERT"], R["C-PLANT-PL"], R["C-FIELD"]
    must_be_prime = {
        "C-PLANT-M": {"d1": M["d1"], "d2": M["d2"], "u": M["u"], "r": M["r"], "v": M["v"]},
        "C-PLANT-P": {"d": Pp["d"], "w": Pp["w"], "r": Pp["r"], "q": Pp["q"]},
        "C-INERT": {"w": I["w"], "r": I["r"], "q": I["q"]},
        "C-PLANT-PL": {"f1": L["f1"], "f2": L["f2"], "f3": L["f3"], "f4": L["f4"], "w": L["w"], "r": L["r"], "q": L["q"]},
        "C-FIELD": {"CF-1": CF["CF-1"], "CF-2": CF["CF-2"]},
    }
    certs = {}
    for c, dd in must_be_prime.items():
        certs[c] = {}
        for k, n in dd.items():
            cr = certify(n)
            cr["sympy_isprime"] = bool(sympy.isprime(n))
            cr["own_bpsw"] = bpsw(n)
            if cr["kind"] == "pratt":
                cr["cert"] = json.loads(json.dumps(cr["cert"]))
            certs[c][k] = cr
    OUT["certificates"] = certs

    # product checks of constructed factorizations
    prod = {
        "C-PLANT-M minus": M["r"] - 1 == 2 * M["d1"] * M["d2"] * M["u"],
        "C-PLANT-M plus": M["r"] + 1 == 4 * 3 * M["v"],
        "C-PLANT-P plus": Pp["r"] + 1 == 4 * 3 * Pp["d"] * Pp["w"],
        "C-PLANT-P minus": Pp["r"] - 1 == 2 * Pp["q"],
        "C-INERT minus": I["r"] - 1 == 2 * I["q"],
        "C-INERT plus": I["r"] + 1 == 4 * 3 * I["w"],
        "C-PLANT-PL plus": L["r"] + 1 == 4 * 3 * L["f1"] * L["f2"] * L["f3"] * L["f4"] * L["w"],
        "C-PLANT-PL minus": L["r"] - 1 == 2 * L["q"],
    }
    OUT["C-PRODUCT_constructed"] = prod

    ev = {}
    fac = {
        ("C-PLANT-M", "minus"): (M["r"], {2: 1, M["d1"]: 1, M["d2"]: 1, M["u"]: 1}),
        ("C-PLANT-M", "plus"): (M["r"], {2: 2, 3: 1, M["v"]: 1}),
        ("C-PLANT-P", "minus"): (Pp["r"], {2: 1, Pp["q"]: 1}),
        ("C-PLANT-P", "plus"): (Pp["r"], {2: 2, 3: 1, Pp["d"]: 1, Pp["w"]: 1}),
        ("C-INERT", "minus"): (I["r"], {2: 1, I["q"]: 1}),
        ("C-INERT", "plus"): (I["r"], {2: 2, 3: 1, I["w"]: 1}),
        ("C-PLANT-PL", "minus"): (L["r"], {2: 1, L["q"]: 1}),
        ("C-PLANT-PL", "plus"): (L["r"], {2: 2, 3: 1, L["f1"]: 1, L["f2"]: 1, L["f3"]: 1, L["f4"]: 1, L["w"]: 1}),
    }
    for (c, b), (r, f) in fac.items():
        ev[f"{c} {b}"] = both(b, r, divisors_from(f), "EXACT")
    ev["C-PLANT-M minus"]["minimiser_in_{D,(r-1)/D}"] = ev["C-PLANT-M minus"]["minimiser"] in (M["D"], (M["r"] - 1) // M["D"])
    ev["C-PLANT-M minus"]["D_vs_(r-1)/D"] = {"D": M["D"], "(r-1)/D": (M["r"] - 1) // M["D"]}
    ev["C-PLANT-P plus"]["minimiser_equals_d"] = ev["C-PLANT-P plus"]["minimiser"] == Pp["d"]
    ev["C-INERT minus"]["minimiser_is_smaller_of_{2,q}"] = ev["C-INERT minus"]["minimiser"] == min(2, I["q"])
    ev["C-INERT plus"]["minimiser_is_12"] = ev["C-INERT plus"]["minimiser"] == 12
    ev["C-PLANT-PL plus"]["minimiser_equals_D_L"] = ev["C-PLANT-PL plus"]["minimiser"] == L["D_L"]
    ev["C-PLANT-PL minus"]["minimiser_is_smaller_of_{2,q}"] = ev["C-PLANT-PL minus"]["minimiser"] == 2
    for k in ev:
        for kk in ("minimiser", "tied"):
            ev[k][kk] = str(ev[k][kk]) if kk == "minimiser" else [str(x) for x in ev[k][kk]]
    OUT["exact_evaluations"] = ev

    # C-BOUND declared states
    bnd = {}
    mM = M["r"] - 1; mP = Pp["r"] + 1
    states = {
        "BND-1": ("minus", M["r"], {2: 1, M["u"]: 1}, [M["D"]]),
        "BND-2": ("minus", M["r"], {2: 1}, [M["d1"] * M["d2"] * M["u"]]),
        "BND-3": ("plus", Pp["r"], {2: 1}, [2 * Pp["d"], 3 * Pp["w"]]),
        # Q3b: own declared state
        "OWN-1": ("plus", Pp["r"], {2: 2, Pp["d"]: 1}, [3 * Pp["w"]]),
    }
    for sid, (b, r, Ff, parts) in states.items():
        Fv = 1
        for p, e in Ff.items():
            Fv *= p ** e
        m = r - 1 if b == "minus" else r + 1
        pp = 1
        for x in parts:
            pp *= x
        W = witness_set(Ff, parts)
        res = both(b, r, W, "BOUND")
        res["F_times_parts_equals_m"] = Fv * pp == m
        res["parts_composite"] = [not sympy.isprime(x) for x in parts]
        res["parts_perfect_power"] = [sympy.perfect_power(x) is not False for x in parts]
        res["witness_set"] = [str(x) for x in W]
        res["minimiser"] = str(res["minimiser"]); res["tied"] = [str(x) for x in res["tied"]]
        bnd[sid] = res
    # BND-1 consistency: upper bound equals C-PLANT-M exact minus exponent within 1e-50
    eb1 = evaluate(PathA, "minus", M["r"], witness_set({2: 1, M["u"]: 1}, [M["D"]]), "BOUND")["e"]
    eex = evaluate(PathA, "minus", M["r"], divisors_from({2: 1, M["d1"]: 1, M["d2"]: 1, M["u"]: 1}), "EXACT")["e"]
    bnd["BND-1"]["consistency_abs_diff"] = mpmath.nstr(abs(eb1 - eex), 10)
    bnd["BND-1"]["consistency_holds"] = abs(eb1 - eex) <= mpmath.mpf(10) ** -50
    bnd["BND-1"]["witness_is_min(D,2u)"] = bnd["BND-1"]["minimiser"] == str(min(M["D"], 2 * M["u"]))
    bnd["BND-2"]["witness_is_2"] = bnd["BND-2"]["minimiser"] == "2"
    bnd["BND-3"]["witness_is_2d"] = bnd["BND-3"]["minimiser"] == str(2 * Pp["d"])
    bnd["BND-3"]["W_matches_text_list"] = sorted(int(x) for x in bnd["BND-3"]["witness_set"]) == sorted(
        [1, 2, 2 * Pp["d"], 4 * Pp["d"], 3 * Pp["w"], 6 * Pp["w"], 6 * Pp["d"] * Pp["w"], 12 * Pp["d"] * Pp["w"]])
    # contrast (superseded single-cofactor formula) for BND-3
    Wc = witness_set({2: 1}, [6 * Pp["d"] * Pp["w"]])
    c = evaluate(PathA, "plus", Pp["r"], Wc, "BOUND")
    bnd["BND-3"]["contrast_single_cofactor"] = {"W": [str(x) for x in Wc], "witness": str(c["minimiser"]), "bin": c["bin"]}
    OUT["C-BOUND"] = bnd

    # C-FIELD / hasse arithmetic (h values as the text states them: 8 for Ed25519-L, 1 for P-256)
    cf = {}
    for cid, n, h in (("CF-1", CF["CF-1"], 8), ("CF-2", CF["CF-2"], 1)):
        p = n  # extraction_cross_check gate requires p (extracted) == case value
        lhs = abs(p + 1 - h * n); rhs = 2 * isqrt(p) + 2
        cf[cid] = {"value": str(n), "bits": n.bit_length(), "h": h, "hasse_lhs": str(lhs), "hasse_rhs": str(rhs),
                   "hasse_fires": lhs > rhs,
                   "reasons_corrected_FP": ["field_prime"] + (["hasse"] if lhs > rhs else []),
                   "reasons_mutation_clause1_disabled": (["hasse"] if lhs > rhs else [])}
    # collisions of construction integers with the two closed-form field primes
    allint = {f"{c}.{k}": n for c, dd in must_be_prime.items() if c != "C-FIELD" for k, n in dd.items()}
    cf["construction_integers_equal_to_CF"] = [k for k, n in allint.items() if n in (CF["CF-1"], CF["CF-2"])]
    cf["construction_r_top_hex"] = {c: hex(R[c]["r"])[:12] for c in ("C-PLANT-M", "C-PLANT-P", "C-INERT", "C-PLANT-PL")}
    OUT["C-FIELD"] = cf

    # Q4 boundary arithmetic at exactly 150 significant digits (Decimal)
    from decimal import Context
    out4 = {}
    for prec in (150, 200):
        ctx = Context(prec=prec)
        tau = Decimal(10) ** -45
        s0 = ctx.add(Decimal(3) / 4, tau)
        ulp = Decimal(10) ** (-prec)  # s in [0.1, 1): last significant place 10^-prec
        rows = {}
        for lab, s in (("below", ctx.subtract(s0, ulp)), ("at", s0), ("above", ctx.add(s0, ulp))):
            flag = abs(s - Decimal(1) / 4) <= tau or abs(s - Decimal(3) / 4) <= tau
            if flag:
                bexact = "INTERMEDIATE" if abs(s - Decimal(3) / 4) <= tau else "NEAR_CEILING"; clause = "(i) flag"
            elif s >= Decimal(3) / 4 + tau:
                bexact = "NEAR_FLOOR"; clause = "(ii)"
            elif s <= Decimal(1) / 4 - tau:
                bexact = "NEAR_CEILING"; clause = "(iii)"
            else:
                bexact = "INTERMEDIATE"; clause = "(iv)"
            if (not flag) and s >= Decimal(3) / 4 + tau:
                bb, bal = "NEAR_FLOOR", "NEAR_FLOOR"
            else:
                bb, bal = "UNDETERMINED", bexact
            rows[lab] = {"s": str(s), "boundary_flag": flag, "EXACT_bin": bexact, "EXACT_clause": clause,
                         "BOUND_bin": bb, "BOUND_bin_at_least": bal}
        out4[f"prec_{prec}"] = rows
    OUT["Q4"] = out4
    # verifier self-tests (positive and tamper, mirroring admission items 4 and 5 for MY verifier)
    c89 = gp_primecert(2 ** 89 - 1)
    tam = [list(s) for s in c89]; tam[0][0] = 2 ** 89 + 1
    c607 = gp_primecert(2 ** 607 - 1)
    OUT["own_verifier_selftests"] = {
        "accepts_2^89-1": verify_ecpp(c89, 2 ** 89 - 1)[0],
        "accepts_2^607-1": verify_ecpp(c607, 2 ** 607 - 1)[0],
        "rejects_tampered_top_N_2^89+1": not verify_ecpp(tam, 2 ** 89 + 1)[0],
        "pratt_rejects_wrong_witness": not verify_pratt({"p": 7, "kind": "pratt", "a": 2, "factors": {"2": 1, "3": 1},
                                                         "sub": [{"p": 3, "kind": "pratt", "a": 2, "factors": {"2": 1}, "sub": []}]}),
    }
    OUT["tool_versions"] = {"python": sys.version, "sympy": sympy.__version__, "mpmath": mpmath.__version__,
                            "pyyaml": yaml.__version__,
                            "gp": subprocess.run(["gp", "--version-short"], capture_output=True, text=True).stdout.strip()}
    OUT["total_seconds"] = round(time.time() - t0, 1)

def enc(o):
    if isinstance(o, (mpmath.mpf,)):
        return mpmath.nstr(o, 60)
    if isinstance(o, Decimal):
        return str(o)
    if isinstance(o, int):
        return str(o)
    raise TypeError(type(o))

if __name__ == "__main__":
    main()
    json.dump(OUT, open(sys.argv[1], "w"), indent=1, default=enc)
    print("done", OUT["total_seconds"])
